	private static void assertPlanes(AdjacencySourceScanner scanner, boolean outgoing, boolean explicit,
			int expectedPlane) throws Exception {
		List<Integer> planes = new ArrayList<>();
		AdjacencySourceScanner.GroupConsumer consumer = new AdjacencySourceScanner.GroupConsumer() {

			@Override
			public void begin(long key, long predicate, int plane) {
				planes.add(plane);
			}

			@Override
			public void pair(long neighbor, long context) {
			}

			@Override
			public void end() {
			}
		};
		if (outgoing) {
			scanner.scanOutgoing(explicit, consumer);
		} else {
			scanner.scanIncoming(explicit, consumer);
		}
		assertThat(planes).containsOnly(expectedPlane);
	}

	private static long uri(long payload) {
		return ValueIds.createId(ValueIds.T_URI, payload);
	}
